from rules import dependencies, in_range, intersect


def _acyclic(chosen, features):
    graph = {
        name: [dep for dep, _ in dependencies(row.get('deps', []), features)]
        for name, row in chosen.items()
    }
    visiting = set()
    visited = set()

    def visit(name):
        if name in visiting:
            return False
        if name in visited:
            return True
        visiting.add(name)
        for dep in graph.get(name, []):
            if dep in graph and not visit(dep):
                return False
        visiting.remove(name)
        visited.add(name)
        return True

    return all(visit(name) for name in graph)


def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', []) or []
    names = sorted(packages)

    needed = {}
    for name, spec in roots.items():
        merged = intersect(needed.get(name), spec)
        if merged is None:
            return {'error': 'unsatisfiable'}
        needed[name] = merged

    best_vector = None
    best_versions = None

    def search(chosen, constraints):
        nonlocal best_vector, best_versions

        for name, row in chosen.items():
            if name not in constraints or not in_range(row['version'], constraints[name]):
                return

        pending = sorted(name for name in constraints if name not in chosen)
        if not pending:
            if not _acyclic(chosen, features):
                return
            versions = {name: row['version'] for name, row in chosen.items()}
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
            return

        name = pending[0]
        forbidden = blocked.get(name, [])
        for row in packages.get(name, []):
            version = row['version']
            if version in forbidden or not in_range(version, constraints[name]):
                continue
            if name in pins and version != pins[name]:
                continue

            next_constraints = dict(constraints)
            valid = True
            for dep_name, dep_range in dependencies(row.get('deps', []), features):
                merged = intersect(next_constraints.get(dep_name), dep_range)
                if merged is None:
                    valid = False
                    break
                next_constraints[dep_name] = merged

            if valid:
                next_chosen = dict(chosen)
                next_chosen[name] = row
                search(next_chosen, next_constraints)

    search({}, needed)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def _bounds(spec):
    if spec is None:
        return (None, None)
    if isinstance(spec, dict):
        for key in ('range', 'versions'):
            if key in spec:
                return _bounds(spec[key])
        if 'version' in spec:
            return _bounds(spec['version'])
        low = spec.get('min', spec.get('minimum', spec.get('min_version', spec.get('>='))))
        high = spec.get('max', spec.get('maximum', spec.get('max_version', spec.get('<='))))
        if '>' in spec:
            low = spec['>'] + 1
        if '<' in spec:
            high = spec['<'] - 1
        return (low, high)
    if isinstance(spec, (list, tuple)) and len(spec) == 2:
        return (spec[0], spec[1])
    if isinstance(spec, int):
        return (spec, spec)
    return (None, None)


def intersect(left, right):
    a = _bounds(left)
    b = _bounds(right)
    low = b[0] if a[0] is None else a[0] if b[0] is None else max(a[0], b[0])
    high = b[1] if a[1] is None else a[1] if b[1] is None else min(a[1], b[1])
    if low is not None and high is not None and low > high:
        return None
    return (low, high)


def in_range(version, spec):
    low, high = _bounds(spec)
    return (low is None or version >= low) and (high is None or version <= high)


def _dependency(item):
    if isinstance(item, str):
        return [(item, (None, None))]
    if isinstance(item, (list, tuple)) and item:
        name = item[0]
        if not isinstance(name, str):
            return []
        if len(item) == 1:
            spec = None
        elif len(item) == 3 and all(isinstance(x, int) for x in item[1:]):
            spec = (item[1], item[2])
        else:
            spec = item[1]
        return [(name, _bounds(spec))]
    if isinstance(item, dict):
        name_key = next((key for key in ('name', 'package', 'pkg', 'dependency') if key in item), None)
        if name_key is not None:
            name = item[name_key]
            spec = next((item[key] for key in ('range', 'versions', 'version', 'constraint') if key in item), None)
            if spec is None:
                low = item.get('min', item.get('min_version'))
                high = item.get('max', item.get('max_version'))
                spec = (low, high)
            return [(name, _bounds(spec))] if isinstance(name, str) else []
        return [(name, _bounds(spec)) for name, spec in item.items() if isinstance(name, str)]
    return []


def dependencies(items, features=None):
    enabled = features or []
    result = []
    for item in items or []:
        if isinstance(item, dict):
            feature = item.get('feature')
            if feature and feature not in enabled:
                continue
        result.extend(_dependency(item))
    return result
